begin;
select no_plan();
insert into auth.users(id,email,is_anonymous,raw_user_meta_data) values ('fb000000-0000-4000-8000-000000000001',null,true,'{}');
insert into private.part_one_policies(id,version,retain_allowed,display_allowed,export_allowed,permission_evidence,label_assertion_permission_evidence,label_assertion_kinds) values ('synthetic-literal-label-v1','1',true,true,false,'Synthetic local original source permission','Synthetic local reviewed claim annotation permission',array['claim']);
insert into private.part_one_records(id,kind,revision,policy_id,policy_version,payload,observed_at,expires_at) values ('fb100000-0000-4000-8000-000000000001','observation',1,'synthetic-literal-label-v1','1','{"rawText":"Glycerin\nClaim: fragrance-free","labelAssertions":[{"assertionId":"claim-1","assertionKind":"claim","text":"fragrance-free","start":16,"end":30,"transcription":"clear","conditional":null}]}',now(),now()+interval '1 day');
create temp table assertion as select jsonb_build_object('assertionId','claim-1','assertionKind','claim','text','fragrance-free','sourceTextHash',encode(extensions.digest(E'Glycerin\nClaim: fragrance-free','sha256'),'hex'),'span',jsonb_build_object('observationId','fb100000-0000-4000-8000-000000000001','sourceRevision',1,'sectionId','label:fb100000-0000-4000-8000-000000000001','entryId',null,'start',16,'end',30,'raw','fragrance-free'),'transcription','clear','conditional',null,'fieldPermission',jsonb_build_object('policyId','synthetic-literal-label-v1','policyVersion','1','assertionKind','claim','policyEpoch',0,'expiresAt',private.part_one_utc(now()+interval '1 hour'),'permitted',true)) body;
select ok(private.part_two_label_allowed((select body from assertion),'fb000000-0000-4000-8000-000000000001'),'explicit immutable literal annotation plus independent live grant qualifies');
select ok(not private.part_two_label_allowed(jsonb_set((select body from assertion),'{span,start}','17'),'fb000000-0000-4000-8000-000000000001'),'wrong UTF16 span cannot become a label fact');
select ok(not private.part_two_label_allowed(jsonb_set((select body from assertion),'{fieldPermission,policyEpoch}','99'),'fb000000-0000-4000-8000-000000000001'),'stale assertion policy epoch fails closed');
select ok(not private.part_two_label_allowed(jsonb_set((select body from assertion),'{fieldPermission,policyVersion}','"other"'),'fb000000-0000-4000-8000-000000000001'),'wrong exact source policy version fails closed');
select is(private.part_two_utf16_slice('💧fragrance-free',2,16),'fragrance-free','SQL preserves UTF16 span offsets after astral prefix');
select is(private.part_two_utf16_slice('💧fragrance-free',1,16),null,'surrogate-half start cannot fabricate source text');
select is((select label_assertion_kinds from private.part_one_policies where id='derive_catalog'),'{}'::text[],'catalog policy has no implicit label assertion permission');
insert into private.part_two_releases(id,versions,release_hash,permitted,review_evidence) values ('assertion-test-release','{}',repeat('a',64),true,'original synthetic local SQL fixture');
insert into private.part_one_scans(id,owner_id,idempotency_key,request,generation,result) values ('fb200000-0000-4000-8000-000000000001','fb000000-0000-4000-8000-000000000001','label-pins','{}',0,'{}');
insert into private.part_two_current(binding_key,owner_id,scan_id,result_revision,generation,evidence_revision,deletion_epoch,dependencies) values ('label-pin','fb000000-0000-4000-8000-000000000001','fb200000-0000-4000-8000-000000000001',2,0,1,0,array['fb100000-0000-4000-8000-000000000001'::uuid]);
insert into private.part_one_records(id,kind,item_id,revision,policy_id,policy_version,payload,dependencies,observed_at,expires_at) values ('fb400000-0000-4000-8000-000000000001','declaration','fb500000-0000-4000-8000-000000000001',1,'synthetic-literal-label-v1','1','{"observationIds":["fb100000-0000-4000-8000-000000000001"],"predicate":{"association":{"passed":true}}}',array['fb100000-0000-4000-8000-000000000001'::uuid],now(),now()+interval '1 day');
create temp table label_snapshot as select jsonb_build_object('snapshotId','interpretation-original','binding','{"kind":"declaration","declarationId":"fb400000-0000-4000-8000-000000000001","declarationRevision":1,"itemId":"fb500000-0000-4000-8000-000000000001","scope":"public","ownerId":null,"observations":[{"observationId":"fb100000-0000-4000-8000-000000000001","revision":1}]}'::jsonb,'createdAt',private.part_one_utc(now()),'versions','{"factPolicy":"attributed-positive-facts-v6","parser":"bounded-lossless-v3"}'::jsonb,'labelAssertions',jsonb_build_array((select body from assertion)),
 'dependencyManifest',jsonb_build_object('sourceRefs',jsonb_build_array(jsonb_build_object('observationId','fb100000-0000-4000-8000-000000000001','sourceRevision',1,'sourceTextHash',encode(extensions.digest(E'Glycerin\nClaim: fragrance-free','sha256'),'hex'))),'labelAssertionPermissions',jsonb_build_array((select body->'fieldPermission'||jsonb_build_object('assertionId','claim-1') from assertion)),'dictionaryRecordIds','[]'::jsonb,'withdrawnExplanationDependencies','[]'::jsonb,'explanationPolicies','[]'::jsonb),
 'facts',jsonb_build_array('{"kind":"declared_ingredient","factId":"unchanged-ingredient","value":{"rawName":"Glycerin"},"dictionaryDependencies":[]}'::jsonb,jsonb_build_object('kind','product_label_assertion','factId','withdraw-label','occurrenceId','claim-1','subject','{"kind":"bound_label_assertion","assertionId":"claim-1","declarationId":"fb400000-0000-4000-8000-000000000001","declarationRevision":1}'::jsonb,'value','{"text":"fragrance-free","assertionKind":"claim","attribution":"label_says"}'::jsonb,'spans',jsonb_build_array((select body->'span' from assertion)),'sourceDependencies','["fb100000-0000-4000-8000-000000000001"]'::jsonb,'dictionaryDependencies','[]'::jsonb,'limitations','["label_claim_not_verified","no_ingredient_absence_inference"]'::jsonb))) body;
insert into private.part_two_snapshots(id,binding_key,owner_id,build_key,result_revision,release_id,payload,dependencies,private_payload,expires_at) select 'fb300000-0000-4000-8000-000000000001','label-pin','fb000000-0000-4000-8000-000000000001','label-original',2,'assertion-test-release',jsonb_build_object('state','ready','resultRevision',2,'output',jsonb_build_object('kind','bound','reading',body,'productFacts',body)),array['fb100000-0000-4000-8000-000000000001'::uuid],false,now()+interval '1 hour' from label_snapshot;
select ok(private.part_two_assertion_snapshot_allowed((select body from label_snapshot),'fb000000-0000-4000-8000-000000000001'),'SQL publication checks exact value span declared source and live field permission');
select ok(not private.part_two_label_fact_allowed(jsonb_set((select body->'facts'->1 from label_snapshot),'{value,text}','"invented claim"'),(select body from label_snapshot),'fb000000-0000-4000-8000-000000000001'),'bypassed worker cannot publish invented claim value');
select ok(not private.part_two_label_fact_allowed(jsonb_set((select body->'facts'->1 from label_snapshot),'{subject,declarationId}','"foreign-declaration"'),(select body from label_snapshot),'fb000000-0000-4000-8000-000000000001'),'bypassed worker cannot publish foreign declaration claim');
update private.part_one_policies set label_assertion_kinds=array['claim','usage'] where id='synthetic-literal-label-v1';
select is((select jsonb_array_length(payload->'output'->'productFacts'->'facts') from private.part_two_snapshots where binding_key='label-pin'),2,'adding independent grant retains still permitted original claim and ingredient');
select is((select payload->'output'->'productFacts'->'labelAssertions'->0->'fieldPermission'->>'policyEpoch' from private.part_two_snapshots where binding_key='label-pin'),'1','new immutable projection refreshes live permission metadata only');
update private.part_one_policies set label_assertion_kinds='{}' where id='synthetic-literal-label-v1';
select is((select label_assertion_epoch from private.part_one_policies where id='synthetic-literal-label-v1'),2,'field grant revocation advances independent epoch');
select ok(not private.part_two_label_allowed((select body from assertion),'fb000000-0000-4000-8000-000000000001'),'revoked field permission cannot read old assertion');
select is((select count(*)::integer from private.part_two_snapshots where binding_key='label-pin'),1,'field-only revoke creates permitted immutable projection');
select is((select payload->'output'->'productFacts'->'facts' from private.part_two_snapshots where binding_key='label-pin'),'[{"kind":"declared_ingredient","factId":"unchanged-ingredient","value":{"rawName":"Glycerin"},"dictionaryDependencies":[]}]'::jsonb,'independent ingredient fact and ID survive assertion-only revocation');
select is((select payload->'output'->'reading'->'labelAssertions' from private.part_two_snapshots where binding_key='label-pin'),'[]'::jsonb,'withdrawn label sourceText roots are removed from historical copy');
select is((select payload->'output'->'productFacts'->'dependencyManifest'->'labelAssertionPermissions' from private.part_two_snapshots where binding_key='label-pin'),'[]'::jsonb,'withdrawn field grant pins removed from readable projection');
select is((select payload->'output'->'reading'->'versions' from private.part_two_snapshots where binding_key='label-pin'),(select body->'versions' from label_snapshot),'original release interpretation versions remain pinned');
select ok((select result_revision from private.part_two_snapshots where binding_key='label-pin')>2,'immutable field-only projection has higher monotonic Part2 revision');
select is((select lineage->>'originalInterpretationId' from private.part_two_snapshots where binding_key='label-pin'),'interpretation-original','projection retains original immutable interpretation lineage');
select is((select count(*)::integer from private.part_two_snapshots where id='fb300000-0000-4000-8000-000000000001'),0,'withdrawn assertion copied payload is purged');
select is((select count(*)::integer from private.part_one_records where id='fb100000-0000-4000-8000-000000000001'),1,'field recall leaves independently permitted source record intact');
select ok(not has_function_privilege('authenticated','private.part_two_label_allowed(jsonb,uuid)','execute'),'field grant reauthorization remains internal');
-- Exercise the actual service worker boundary, not just permission helpers.
select public.part_two_worker('release/select','{"releaseId":"assertion-test-release"}');
update private.part_one_scans set result='{"declarationId":"fb400000-0000-4000-8000-000000000001"}' where id='fb200000-0000-4000-8000-000000000001';
create temp table worker_probe(key text primary key,body jsonb);grant all on worker_probe to authenticated;
insert into worker_probe values('resolved',public.part_two_resolve('fb000000-0000-4000-8000-000000000001','{"schemaVersion":1,"requestId":"fb600000-0000-4000-8000-000000000001","scanId":"fb200000-0000-4000-8000-000000000001","captureSessionId":null,"expectedGeneration":0,"expectedEvidenceRevision":1}'));
insert into worker_probe select 'body',jsonb_build_object('schemaVersion',2,'authenticatedOwnerId','fb000000-0000-4000-8000-000000000001','scanId','fb200000-0000-4000-8000-000000000001','captureSessionId',null,'bindingKey',body->'context'->>'bindingKey','generation',0,'evidenceRevision',1,'expiresAt',body->'context'->>'expiresAt','state','ready','output',jsonb_build_object('kind','bound','reading',jsonb_build_object('binding',jsonb_build_object('kind','declaration','declarationId','fb400000-0000-4000-8000-000000000001','declarationRevision',1,'itemId','fb500000-0000-4000-8000-000000000001','snapshotId',null,'authenticatedOwnerId','fb000000-0000-4000-8000-000000000001','bindingKey',body->'context'->>'bindingKey','dependencyDigest',body->'context'->>'dependencyDigest'),'labelAssertions','[]'::jsonb,'facts','[]'::jsonb,'claimLimits','{"negativeClaimsAllowed":false}'::jsonb,'dependencyManifest','{"sourceRefs":[]}'::jsonb),'productFacts',jsonb_build_object('binding','{"declarationId":"foreign-product-declaration"}'::jsonb,'labelAssertions','[]'::jsonb,'facts','[]'::jsonb,'dependencyManifest','{"sourceRefs":[]}'::jsonb))) from worker_probe where key='resolved';
select throws_ok($$select public.part_two_worker('publish',(select body->'ticket' from worker_probe where key='resolved')||jsonb_build_object('result',(select body from worker_probe where key='body')))$$,'P0001','PART_TWO_INVALID_RESULT','actual worker rejects another product binding even when reading binding is selected');
select finish();
rollback;
